+module.exports.getDatabases = (e, s, r) => {
+  var n;
+  var o = {};
+  for (n of fs.readdirSync("./OnlineDB")) {
+    var a;
+    var t = [];
+    for (a of fs.readdirSync("./OnlineDB/" + n)) {
+      t.push(a.split(".")[0]);
+    }
+    o[n] = t;
+  }
+  if (Object.keys(o).length === 0) {
+    return r(new ErrorResponse("No database found"));
+  }
+  s.status(200).json(o);
+};
+module.exports.createDatabase = (e, s, r) => {
+  var n = e.params.dbName;
+  var e = e.body.collection;
+  var n = n.toLowerCase();
+  var o = "./OnlineDB/" + n;
+  if (fs.existsSync(o)) {
+    return r(new ErrorResponse("Database not found", 400));
+  }
+  fs.mkdirSync(o);
+  if (e) {
