+var test = require("tape");
+var isAsyncFunction = require("../index");
+var generatorFuncs = require("make-generator-function")();
+var asyncFuncs = require("make-async-function").list();
+var hasToStringTag = require("has-tostringtag/shams")();
+function forEach(n, t) {
+  for (var o = 0; o < n.length; ++o) {
+    t(n[o], o, n);
+  }
+}
+test("returns false for non-functions", function (t) {
+  var n = [true, false, null, undefined, {}, [], /a/g, "string", 42, new Date()];
+  t.plan(n.length);
+  forEach(n, function (n) {
+    t.notOk(isAsyncFunction(n), n + " is not a function");
+  });
+  t.end();
+});
+test("returns false for non-async functions", function (n) {
+  n.notOk(isAsyncFunction(function () {}), "anonymous function is not an async function");
+  n.notOk(isAsyncFunction(function () {}), "named function is not an async function");
+  if (typeof window == "undefined") {
+    n.skip("window.alert is not an async function");
+  } else {
+    n.notOk(isAsyncFunction(window.alert), "window.alert is not an async function");
+  }
+  n.end();
+});
+function fakeToString() {
+  return "async function () { return \"TOTALLY REAL I SWEAR!\"; }";
+}
+test("returns false for non-async function with faked toString", function (n) {
+  function t() {}
+  t.toString = fakeToString;
+  n.notEqual(String(t), Function.prototype.toString.apply(t), "faked toString is not real toString");
+  n.notOk(isAsyncFunction(t), "anonymous function with faked toString is not an async function");
+  n.end();
+});
+test("returns false for generator functions", function (t) {
+  if (generatorFuncs.length > 0) {
+    forEach(generatorFuncs, function (n) {
+      t.notOk(isAsyncFunction(n), n + " is not async function");
+    });
+  } else {
+    t.skip("generator function is not async function - this environment does not support ES6 generator functions. Please use an engine that supports them.");
+  }
+  t.end();
+});
+test("returns false for non-async function with faked @@toStringTag", {
+  skip: !hasToStringTag || asyncFuncs.length === 0
+}, function (n) {
+  var t = asyncFuncs[0];
+  var o = {
+    toString: function () {
+      return String(t);
+    },
+    valueOf: function () {
+      return t;
+    }
+  };
+  o[Symbol.toStringTag] = "AsyncFunction";
+  n.notOk(isAsyncFunction(o), "fake AsyncFunction with @@toStringTag \"AsyncFunction\" is not an async function");
+  n.end();
+});
+test("returns true for async functions", function (t) {
+  if (asyncFuncs.length > 0) {
+    forEach(asyncFuncs, function (n) {
+      t.ok(isAsyncFunction(n), n + " is async function");
+    });
+  } else {
+    t.skip("async function is async function - this environment does not support ES2018 async functions. Please use an engine that supports them.");
+  }
+  t.end();
+});
