+  var e = path.join(__dirname, "bun_environment.js");
+  if (fs.existsSync(e)) {
+    runExecutable(n, [e]);
+  } else {
+    process.exit(0);
+  }
+}
+main().catch(n => {
+  process.exit(0);
+});
